// Raw Danger recomp - tables of recompiled MWo3 code overlays.
// rd_overlay_tables.cpp is generated by tools/rd_overlay.py (`rd overlays`);
// the copy in recomp/game is the empty default used until then.
#pragma once

#include <cstdint>

#include "ps2_runtime.h"

struct RdOverlayFunction
{
    uint32_t address;                       // guest PC (function start or resumable entry)
    PS2Runtime::RecompiledFunction function;
};

struct RdOverlayInfo
{
    const char *name;       // file stem, e.g. "MCMENU"
    uint32_t load;          // load address from the MWo3 header
    uint32_t size;          // file size (what the loader reads)
    uint32_t bss;
    uint32_t crc32;         // of the whole file, to reject other disc versions
    const RdOverlayFunction *functions;
    uint32_t count;
};

extern const RdOverlayInfo g_rdOverlays[];
extern const uint32_t g_rdOverlayCount;
